"""Build reports/summary.json and serving/samples.json from saved evaluation files.

Every number is read from reports/metrics.json and the per-sentence prediction
files written by evaluate.py. Nothing is typed in by hand. Works for Grade 1
only reports (v2) and for two-grade reports (v3).
"""
import argparse
import json
from pathlib import Path

from braillelm.paths import REPORTS, SERVING

SCOPE = {
    "g1": ("Grade 1 (uncontracted) braille generated by a converter that matches liblouis, from WikiText "
           "sentences never used for training or model selection."),
    "g2": ("Grade 2 (contracted) braille generated by liblouis en-ueb-g2 from WikiText sentences never used for "
           "training or model selection. The baseline is liblouis's own rule-based back-translation."),
}
TAIL = " Not yet validated on braille produced by people or captured by a device; damage is simulated."


def read(path):
    return [json.loads(line) for line in open(path, encoding="utf-8")]


def grade_block(f, grade):
    c = f["clean"]
    rule = c.get("rule_decoder")

    def row(label, mode, neural, base, extra=None):
        r = {"label": label, "mode": mode, "neural": neural["exact"] / neural["n"], "neural_exact": neural["exact"],
             "n": neural["n"], "neural_cer": neural["cer"],
             "rule": base["exact"] / base["n"] if base else None, "rule_exact": base["exact"] if base else None,
             "rule_cer": base["cer"] if base else None}
        r.update(extra or {})
        return r
    noise = [row("Clean braille", "faithful", c["neural"], rule),
             row("Clean braille", "repair", c["neural_repair_mode"], rule)]
    for key in sorted(k for k in f if k.startswith("dot_errors_")):
        rate = float(key.split("_")[-1])
        noise.append(row(f"{rate:.0%} of cells have one wrong dot", "repair", f[key]["neural"],
                         f[key].get("rule_decoder"), {"sentences_damaged": f[key]["inputs_actually_changed"]}))
    block = {"n": c["neural"]["n"], "exact": c["neural"]["exact"], "rate": c["neural"]["exact"] / c["neural"]["n"],
             "wilson95": c["neural"]["wilson95"], "baseline_name": f.get("baseline", "lookup table"),
             "baseline_exact": rule["exact"] if rule else None, "ms_per_sentence": f["ms_per_sentence"],
             "noise": noise, "scope": SCOPE[grade] + TAIL}
    if "has_unseen_word" in c:
        u = c["has_unseen_word"]
        block["unseen"] = {"n": u["n"], "exact": u["exact"], "rate": u["exact"] / u["n"]}
    return block


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--reports", default=str(REPORTS))
    ap.add_argument("--samples_per_grade", type=int, default=8)
    args = ap.parse_args()
    reports = Path(args.reports)
    m = json.loads((reports / "metrics.json").read_text())
    final = m["final_test"]
    if "clean" in final:                       # v2 report: Grade 1 only, not nested by grade
        final = {"g1": dict(final, baseline="lookup table")}
    summary = {"params": m["checkpoint"]["params"], "step": m["checkpoint"].get("step"),
               "model": m.get("model", {}), "test_set": "locked final set (399 unseen sentences)",
               "grades": {g: grade_block(f, g) for g, f in final.items()}}
    (reports / "summary.json").write_text(json.dumps(summary, indent=2))

    # Demo samples: fixed positions in the locked set, chosen without looking at any model output.
    samples = []
    for g in summary["grades"]:
        path = reports / f"final_test_{g}_predictions.jsonl"
        if not path.exists():
            path = reports / "final_test_predictions.jsonl"
        rows = read(path)
        short = [i for i, r in enumerate(rows) if 40 <= len(r["print"]) <= 95]
        stride = max(1, len(short) // args.samples_per_grade)
        for i in short[::stride][:args.samples_per_grade]:
            r = rows[i]
            samples.append({"grade": g, "label": " ".join(r["print"].split()[:3]) + " …", "braille": r["braille"],
                            "print": r["print"], "baseline": r.get("baseline"), "row": i})
    (SERVING / "samples.json").write_text(json.dumps(samples, ensure_ascii=False, indent=1), encoding="utf-8")
    print(json.dumps({g: {k: b[k] for k in ("n", "exact", "baseline_exact")} for g, b in summary["grades"].items()}))


if __name__ == "__main__":
    main()
